/*
 * Reads GetLastError; for a nonzero code, asks FormatMessageA for an allocated
 * message, logs ERROR:, apiName and the message through Gfx_DebugPrint, frees
 * the message with LocalFree and clears the last-error code.
 */
// FUNCTION: FF7 0x006a68f0
void __cdecl Gl_LogWin32Error(const char *apiName)
{
    char *message;
    DWORD errorCode;
    errorCode = GetLastError();
    if (errorCode != 0) {
        FormatMessageA(0x1100, 0, errorCode, 0x400, (char *)&message, 0, 0);
        // STRING: FF7 0x00917214
        Gfx_DebugPrint("ERROR: ");
        Gfx_DebugPrint(apiName);
        // STRING: FF7 0x0091721c
        Gfx_DebugPrint("\n  ");
        Gfx_DebugPrint(message);
        LocalFree(message);
        SetLastError(0);
    }
}

/*
 * Consumes glGetError; for a nonzero result, logs message followed by a newline and
 * the numeric GL error through Gfx_DebugPrint. Returns silently when no GL
 * error is pending.
 */
// FUNCTION: FF7 0x006a696b
void __cdecl Gl_CheckError(const char *message)
{
    unsigned int errorCode;
    char buffer[200];
    errorCode = glGetError();
    if (errorCode == 0) {
        return;
    }
    Gfx_DebugPrint(message);
    // STRING: FF7 0x00917220
    Gfx_DebugPrint("\n");
    // STRING: FF7 0x00917224
    sprintf(buffer, "GL ERROR: %d \n", errorCode);
    Gfx_DebugPrint(buffer);
}

/*
 * Consumes glGetError; for a nonzero result, logs message followed by a newline and
 * the numeric GL error together with value through Gfx_DebugPrint. Returns
 * silently when no GL error is pending.
 */
// FUNCTION: FF7 0x006a69c9
void __cdecl Gl_CheckErrorWithValue(const char *message, int value)
{
    unsigned int errorCode;
    char buffer[200];
    errorCode = glGetError();
    if (errorCode == 0) {
        return;
    }
    Gfx_DebugPrint(message);
    // STRING: FF7 0x00917234
    Gfx_DebugPrint("\n");
    // STRING: FF7 0x00917238
    sprintf(buffer, "GL ERROR: %d %d \n", errorCode, value);
    Gfx_DebugPrint(buffer);
}

