/*
 * Queries and returns the low byte of OpenGL's double-buffered state.
 */
// FUNCTION: FF7 0x006a6b73
int __cdecl Gl_IsDoubleBuffered(void)
{
    int enabled;

    glGetBooleanv(GL_DOUBLEBUFFER, (unsigned char *)&enabled);
    return enabled & 0xFF;
}

