/*
 * Presents current frame to display surface via swap buffers or bit blit.
 */
// FUNCTION: FF7 0x006a7157
void __cdecl Gl_PresentFrame(GlContext *ctx)
{
    HDC hdc;
    glFlush();
    if (ctx->initFlag != 0) {
        hdc = GetDC((HWND)GetEngineContext()->hwnd);
        if (hdc != 0) {
            if (SwapBuffers(hdc) != 0) { /* empty first arm: lib/codegen.h */
            } else {
                // STRING: FF7 0x009174b0
                Gl_LogWin32Error("SwapBuffers");
            }
            ReleaseDC((HWND)GetEngineContext()->hwnd, hdc);
        }
    }
}

