/*
 * Clears the specified color, depth, and stencil buffers.
 */
// FUNCTION: FF7 0x006a71ff
void __cdecl Gl_ClearBuffers(float red, float green, float blue, float alpha, int clearColor, int clearDepth)
{
    int clearMask;
    clearMask = 0;
    if (clearDepth != 0) {
        glDepthMask(1);
        glClearDepth(1.0);
        clearMask |= 0x100;
    }
    if (clearColor != 0) {
        glClearColor(red, green, blue, alpha);
        clearMask |= 0x4000;
    }
    if (clearMask != 0)
        glClear(clearMask);
}

